package ai.novita.sandbox.core; import java.util.*; public class SecretBinding { private String name; @com.google.gson.annotations.SerializedName(value="placeholder", alternate={"placeholder_value"}) private String placeholder; private String description,status; @com.google.gson.annotations.SerializedName(value="hosts", alternate={"allowed_hosts"}) private List<String> hosts; @com.google.gson.annotations.SerializedName(value="hasSecret", alternate={"has_secret"}) private boolean hasSecret; public String getName(){return name;} public List<String> getHosts(){return hosts;} public String getPlaceholder(){return placeholder;} public String getDescription(){return description;} public String getStatus(){return status;} public boolean hasSecret(){return hasSecret;} }
